import React from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

const months = [
  'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
  'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
];

const InformeMensual = ({ reportData, formatCLP }) => {
  if (!reportData || Object.keys(reportData).length === 0 || reportData.error) {
    return (
      <div className="text-gray-400 py-12 text-center">
        No hay datos para el mes seleccionado o hubo un error.
      </div>
    );
  }

  // Ejemplo: reportData.salesByDay = [total de cada día del mes]
  // reportData.topProducts = [{name, sold}]
  // reportData.breakdownByPayment = {efectivo: {cantidad, total}, tarjeta: {cantidad, total}}

  // Prepara datos para el gráfico (ventas por día del mes)
  const chartData = (reportData.salesByDay || []).map((val, idx) => ({
    dia: idx + 1,
    ventas: val,
  }));

  return (
    <div className="space-y-8">
      <div className="bg-white rounded-lg shadow p-6 mb-4">
        <h2 className="text-xl font-bold text-indigo-700 mb-2">Resumen mensual</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div>
            <span className="text-gray-500 text-sm">💰 Total ventas</span>
            <div className="text-2xl font-bold text-indigo-700">{formatCLP(reportData.totalSales)}</div>
            <div className="text-xs text-gray-400">Monto total vendido en el mes.</div>
          </div>
          <div>
            <span className="text-gray-500 text-sm">🛒 N° de ventas</span>
            <div className="text-2xl font-bold text-indigo-700">{reportData.salesCount}</div>
            <div className="text-xs text-gray-400">Cantidad de compras realizadas.</div>
          </div>
          <div>
            <span className="text-gray-500 text-sm">🧾 Ticket promedio</span>
            <div className="text-2xl font-bold text-indigo-700">{formatCLP(reportData.avgTicket)}</div>
            <div className="text-xs text-gray-400">Promedio gastado por cada cliente en una compra.</div>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow p-6 mb-4">
        <h3 className="font-semibold mb-2 text-indigo-700">Métodos de pago</h3>
        <ul className="space-y-1">
          {Object.entries(reportData.breakdownByPayment || {}).map(([metodo, val]) => (
            <li key={metodo} className="flex justify-between">
              <span className="capitalize">{metodo}:</span>
              <span>
                {val.cantidad} ventas ({formatCLP(val.total)})
              </span>
            </li>
          ))}
        </ul>
      </div>

      <div className="bg-white rounded-lg shadow p-6 mb-4">
        <h3 className="font-semibold mb-2 text-indigo-700">Top productos vendidos</h3>
        {reportData.topProducts && reportData.topProducts.length > 0 ? (
          <ol className="list-decimal list-inside space-y-1">
            {reportData.topProducts.map((prod, idx) => (
              <li key={prod.name || idx}>
                <span className="font-medium">{prod.name}</span>
                <span className="text-gray-500"> ({prod.sold} unds)</span>
              </li>
            ))}
          </ol>
        ) : (
          <div className="text-gray-400">No hay productos vendidos este mes.</div>
        )}
      </div>

      <div className="bg-white rounded-lg shadow p-6">
        <h3 className="font-semibold mb-2 text-indigo-700">Ventas por día del mes</h3>
        <ResponsiveContainer width="100%" height={220}>
          <BarChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="dia" />
            <YAxis tickFormatter={formatCLP} />
            <Tooltip formatter={formatCLP} />
            <Bar dataKey="ventas" fill="#6366f1" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default InformeMensual;
